'use client'
import { useEffect, useMemo, useRef } from 'react'
import { startAbstractCanvas, type Moment } from '@/lib/effects/abstract'
import { abstractSet, type AbstractKind, type Cluster, type Tag } from '@/lib/effects/abstract-kinds'
import { cn } from '@/lib/cn'

// The site's abstract canvases (abstract/Abstract): an ASCII drawing in a 14:13 panel on the raised surface, drawn on a
// canvas while it is on screen. `archive`: a brand's records as rows of characters, new days arriving at the top and
// older ones packing toward the foot. `tags`: a field of characters resolving into tags one at a time. `graph`: the
// brand in the middle linked to clusters of its records. With reduced motion it shows the settled frame; `freeze`
// holds a moment (start, middle or settled). The canvas is hidden from assistive tech and a line says what it shows.
export type { AbstractKind, Cluster, Tag }
export interface AbstractCanvasProps {
  /** archive, tags or graph. */
  kind?: AbstractKind
  /** The tags the field resolves into (tags). */
  tags?: Tag[]
  /** The brand in the middle (graph). */
  brand?: string
  /** The clusters around it (graph). */
  clusters?: Cluster[]
  /** Hold one moment: start, middle or settled. */
  freeze?: Moment
  className?: string
}

export function AbstractCanvas({ kind = 'archive', tags, brand, clusters, freeze, className }: AbstractCanvasProps) {
  const ref = useRef<HTMLCanvasElement>(null)
  const set = useMemo(() => abstractSet(kind, { tags, brand, clusters }), [kind, tags, brand, clusters])
  useEffect(() => {
    const canvas = ref.current
    return canvas ? startAbstractCanvas(canvas, set.draw, { fps: set.fps, moments: set.moments, freeze }) : undefined
  }, [set, freeze])
  return (
    <div data-ds="abstract-canvas" data-name={set.name} className={cn('relative aspect-[14/13] overflow-hidden rounded-panel bg-surface-raised select-none', className)}>
      <canvas ref={ref} aria-hidden="true" className="absolute inset-0 block size-full" />
      <p className="sr-only">{set.summary}</p>
    </div>
  )
}

/** The archive rows. */
export const ArchiveRows = (props: Omit<AbstractCanvasProps, 'kind'>) => <AbstractCanvas kind="archive" {...props} />
/** The tag field. */
export const TagField = (props: Omit<AbstractCanvasProps, 'kind'>) => <AbstractCanvas kind="tags" {...props} />
/** The brand graph. */
export const BrandGraph = (props: Omit<AbstractCanvasProps, 'kind'>) => <AbstractCanvas kind="graph" {...props} />

export default AbstractCanvas

// The site's abstract canvases (abstract/useAbstractCanvas): ASCII drawings on a 2D canvas in the brand's tokens,
// painted at a fixed frame rate while on screen and asleep off it; with reduced motion one settled frame, and `freeze`
// holds a chosen moment (start, middle or settled). Shared by both flavors.

export const CELL_W = 8;
export const CELL_H = 16;
export const RAMP = " .:-=+*#";

export type Tokens = {
  text: string;
  text2: string;
  text3: string;
  line: string;
  lineStrong: string;
  surface: string;
  bg: string;
  mono: string;
  body: string;
  easeLoop: Bezier;
  easeOut: Bezier;
  ms: (name: string) => number;
  px: (name: string) => number;
  bez: (name: string, fallback: Bezier) => Bezier;
};

export type Env = {
  w: number;
  h: number;
  dpr: number;
  tokens: Tokens;
  glyph: (level: number, x: number, y: number, alpha: number) => void;
};

export type Draw = (ctx: CanvasRenderingContext2D, t: number, env: Env) => void;

export type Bezier = [number, number, number, number];

export function bezier([x1, y1, x2, y2]: Bezier, p: number) {
  if (p <= 0) return 0;
  if (p >= 1) return 1;
  const cx = 3 * x1;
  const bx = 3 * (x2 - x1) - cx;
  const ax = 1 - cx - bx;
  const cy = 3 * y1;
  const by = 3 * (y2 - y1) - cy;
  const ay = 1 - cy - by;
  const x = (s: number) => ((ax * s + bx) * s + cx) * s;
  let s = p;
  for (let i = 0; i < 6; i++) {
    const d = (3 * ax * s + 2 * bx) * s + cx;
    if (Math.abs(d) < 1e-6) break;
    s -= (x(s) - p) / d;
  }
  if (s < 0 || s > 1 || Math.abs(x(s) - p) > 1e-4) {
    let lo = 0;
    let hi = 1;
    s = p;
    for (let i = 0; i < 24; i++) {
      if (x(s) < p) lo = s;
      else hi = s;
      s = (lo + hi) / 2;
    }
  }
  return ((ay * s + by) * s + cy) * s;
}

const parseBezier = (raw: string, fallback: Bezier): Bezier => {
  const m = raw.match(/cubic-bezier\(([^)]+)\)/);
  if (!m) return fallback;
  const n = m[1].split(",").map(Number);
  return n.length === 4 && n.every(Number.isFinite) ? (n as Bezier) : fallback;
};

// The site's names the drawings ask for, read as the library's tokens.
const NAMES: Record<string, string> = {
  "--text": "--ds-color-fg",
  "--text-2": "--ds-color-fg-soft",
  "--text-3": "--ds-color-fg-muted",
  "--line": "--ds-color-edge",
  "--line-strong": "--ds-color-edge-strong",
  "--surface": "--ds-color-surface-raised",
  "--bg": "--ds-color-surface",
  "--font-ascii": "--ds-font-ascii",
  "--font-body": "--ds-font-text",
  "--ease-loop": "--ds-easing-loop",
  "--ease-out": "--ds-easing-out",
  "--caption-size": "--ds-text-caption",
  "--radius-m": "--ds-radius-panel",
  "--space-8": "--ds-space-sm",
  "--space-16": "--ds-space-lg",
  "--space-24": "--ds-space-xl",
  "--space-64": "--ds-space-4xl",
  "--search-drift": "--ds-abstract-drift",
  "--dur-abstract-line": "--ds-abstract-line",
  "--dur-abstract-line-step": "--ds-abstract-line-step",
  "--dur-abstract-glide": "--ds-abstract-glide",
  "--dur-abstract-gather": "--ds-abstract-gather",
  "--dur-abstract-decode": "--ds-abstract-decode",
  "--dur-abstract-tag-step": "--ds-abstract-tag-step",
  "--dur-loop-step": "--ds-abstract-loop-step",
  "--dur-proof-stagger": "--ds-abstract-stagger",
  "--dur-proof-swap": "--ds-abstract-swap",
  "--ease-proof": "--ds-abstract-ease",
};

function readTokens(el: Element): Tokens {
  const css = getComputedStyle(el);
  const v = (name: string) => css.getPropertyValue(NAMES[name] ?? name).trim();
  return {
    text: v("--text"),
    text2: v("--text-2"),
    text3: v("--text-3"),
    line: v("--line"),
    lineStrong: v("--line-strong"),
    surface: v("--surface"),
    bg: v("--bg"),
    mono: v("--font-ascii") || "monospace",
    body: v("--font-body") || "sans-serif",
    easeLoop: parseBezier(v("--ease-loop"), [0.4, 0, 0.2, 1]),
    easeOut: parseBezier(v("--ease-out"), [0.22, 1, 0.36, 1]),
    ms: (name: string) => {
      const raw = v(name);
      const n = parseFloat(raw) || 0;
      return raw.endsWith("ms") ? n : raw.endsWith("s") ? n * 1000 : n;
    },
    px: (name: string) => parseFloat(v(name)) || 0,
    bez: (name: string, fallback: Bezier) => parseBezier(v(name), fallback),
  };
}

function glyphAtlas(family: string, white: string, dpr: number) {
  const atlas = document.createElement("canvas");
  atlas.width = Math.ceil(CELL_W * RAMP.length * dpr);
  atlas.height = Math.ceil(CELL_H * dpr);
  const a = atlas.getContext("2d");
  if (a) {
    a.scale(dpr, dpr);
    a.fillStyle = white;
    a.font = `13.333px ${family}`;
    a.textAlign = "center";
    a.textBaseline = "alphabetic";
    for (let i = 1; i < RAMP.length; i++) a.fillText(RAMP[i], i * CELL_W + CELL_W / 2, 12);
  }
  return atlas;
}

export type Moment = "start" | "middle" | "settled";
export type Moments = (ms: (name: string) => number) => Record<Moment, number>;

/** Draws `draw` on the canvas at `fps` while it is on screen, or one fixed moment (`freeze`, or `still` with reduced motion). */
export function startAbstractCanvas(
  canvas: HTMLCanvasElement,
  draw: Draw,
  {
    fps,
    moments,
    still = "settled",
    freeze,
  }: {
    fps: number;
    moments: Moments;
    still?: Moment;
    freeze?: Moment;
  },
): () => void {
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)");
    let ctx: CanvasRenderingContext2D | null = null;
    let env: Env | null = null;
    let near = false;
    let onScreen = false;
    let raf = 0;
    let clock = 0;
    let last = 0;
    let lastDraw = -Infinity;
    const frame = 1000 / fps;

    const setup = () => {
      ctx = canvas.getContext("2d");
      if (!ctx) return;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const w = canvas.clientWidth;
      const h = canvas.clientHeight;
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
      const tokens = readTokens(canvas);
      const atlas = glyphAtlas(tokens.mono, tokens.text, dpr);
      const c = ctx;
      env = {
        w,
        h,
        dpr,
        tokens,
        glyph: (level, x, y, alpha) => {
          if (level <= 0 || alpha <= 0) return;
          c.globalAlpha = Math.min(alpha, 1);
          c.drawImage(atlas, level * CELL_W * dpr, 0, CELL_W * dpr, CELL_H * dpr, x, y, CELL_W, CELL_H);
        },
      };
    };

    const paint = (t: number) => {
      if (!ctx || !env) return;
      ctx.setTransform(env.dpr, 0, 0, env.dpr, 0, 0);
      ctx.globalAlpha = 1;
      ctx.clearRect(0, 0, env.w, env.h);
      draw(ctx, t, env);
      ctx.globalAlpha = 1;
    };

    const at = (m: Moment) => (env ? moments(env.tokens.ms)[m] : 0);
    const fixed = () => (freeze !== undefined ? at(freeze) : reduce.matches ? at(still) : null);
    const playing = () => near && onScreen && document.visibilityState === "visible" && fixed() === null;

    const tick = (now: number) => {
      raf = requestAnimationFrame(tick);
      clock += Math.min(now - last, 100);
      last = now;
      if (clock - lastDraw < frame - 1) return;
      lastDraw = clock - (clock % frame);
      paint(lastDraw);
    };
    const sync = () => {
      if (playing()) {
        if (!raf) {
          last = performance.now();
          raf = requestAnimationFrame(tick);
        }
      } else if (raf) {
        cancelAnimationFrame(raf);
        raf = 0;
      }
    };
    const refresh = () => {
      if (!near) return;
      setup();
      const f = fixed();
      paint(f !== null ? f : lastDraw === -Infinity ? 0 : lastDraw);
      sync();
    };

    const approach = new IntersectionObserver(
      ([entry]) => {
        if (!entry.isIntersecting) return;
        approach.disconnect();
        near = true;
        refresh();
        const t = env?.tokens;
        if (t) {
          Promise.all([
            document.fonts.load(`13.333px ${t.mono}`, RAMP),
            document.fonts.load(`12px ${t.body}`),
          ]).then(
            () => refresh(),
            () => {},
          );
        }
      },
      { rootMargin: "100% 0px" },
    );
    const view = new IntersectionObserver(
      ([entry]) => {
        onScreen = entry.isIntersecting;
        sync();
      },
      { threshold: 0.25 },
    );
    let width = canvas.clientWidth;
    let resizeFrame = 0;
    const resize = new ResizeObserver(() => {
      if (canvas.clientWidth === width) return;
      width = canvas.clientWidth;
      cancelAnimationFrame(resizeFrame);
      resizeFrame = requestAnimationFrame(refresh);
    });

    approach.observe(canvas);
    view.observe(canvas);
    resize.observe(canvas);
    document.addEventListener("visibilitychange", sync);
    reduce.addEventListener("change", refresh);
    return () => {
      approach.disconnect();
      view.disconnect();
      resize.disconnect();
      cancelAnimationFrame(raf);
      cancelAnimationFrame(resizeFrame);
      document.removeEventListener("visibilitychange", sync);
      reduce.removeEventListener("change", refresh);
    };
}

export const hash = (a: number, b = 0, c = 0) => {
  const s = Math.sin(a * 127.1 + b * 311.7 + c * 74.7) * 43758.5453;
  return s - Math.floor(s);
};

export function noise(x: number, y: number, z = 0) {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const xf = x - xi;
  const yf = y - yi;
  const u = xf * xf * (3 - 2 * xf);
  const v = yf * yf * (3 - 2 * yf);
  const a = hash(xi, yi, z);
  const b = hash(xi + 1, yi, z);
  const c = hash(xi, yi + 1, z);
  const d = hash(xi + 1, yi + 1, z);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}

export const clamp01 = (x: number) => Math.min(1, Math.max(0, x));

import { archiveMoments, drawArchive } from '@/lib/effects/abstract-archive'
import { graphMoments, makeDrawGraph, type Cluster } from '@/lib/effects/abstract-graph'
import { makeDrawTags, tagMoments, type Tag } from '@/lib/effects/abstract-tags'
import type { Draw, Moments } from '@/lib/effects/abstract'

// The three abstract canvases (abstract/Abstract): what each draws, at what frame rate, its moments and the line read
// to assistive tech. Data comes through props; the defaults are Acme's.
export type AbstractKind = 'archive' | 'tags' | 'graph'
export type { Cluster, Tag }

export const ACME_TAGS: Tag[] = [
  { label: 'Hook', value: 'Before and after' },
  { label: 'Angle', value: 'Saves time' },
  { label: 'Persona', value: 'Busy parent' },
]
export const ACME_CLUSTERS: Cluster[] = [
  { label: 'Ads', angle: -150, count: 5 },
  { label: 'Landing pages', angle: -30, count: 4 },
  { label: 'Organic posts', angle: 150, count: 5 },
  { label: 'Creators', angle: 30, count: 4 },
]

export interface AbstractSet { name: string, draw: Draw, fps: number, moments: Moments, summary: string }

export function abstractSet(kind: AbstractKind, { tags = ACME_TAGS, brand = 'Acme', clusters = ACME_CLUSTERS }: { tags?: Tag[], brand?: string, clusters?: Cluster[] } = {}): AbstractSet {
	if (kind === 'tags') {
		return {
			name: 'It is pre-analyzed',
			draw: makeDrawTags(tags),
			fps: 30,
			moments: (ms) => tagMoments(ms, tags.length),
			summary: `A field of characters resolves into tags, one at a time: ${tags.map((t) => `${t.label.toLowerCase()}, ${t.value}`).join('; ')}.`,
		}
	}
	if (kind === 'graph') {
		return {
			name: 'It is one graph',
			draw: makeDrawGraph(brand, clusters),
			fps: 60,
			moments: graphMoments,
			summary: `${brand} in the middle, linked to its ${clusters.map((c) => c.label.toLowerCase()).join(', ')}, and those records linked to each other.`,
		}
	}
	return {
		name: 'It remembers',
		draw: drawArchive,
		fps: 30,
		moments: archiveMoments,
		summary: "A brand's records as rows of characters, today at the top. New days arrive and older ones sink and pack together toward the foot, kept from a week, a month and a year ago.",
	}
}

// The archive rows drawing (abstract/archive): a brand's records as rows of characters, today at the top; new days
// arrive and older ones sink and pack toward the foot.
import { CELL_H, CELL_W, bezier, clamp01, hash, noise, type Draw } from "@/lib/effects/abstract";

const BASE = 400;
const BURST = 4;
const FULL = 5;
const MARKS: [number, string][] = [
  [0, "Today"],
  [7, "1 week"],
  [30, "1 month"],
  [365, "1 year"],
];

type Timing = { step: number; line: number; glide: number; hold: number; cycle: number };
const timing = (ms: (n: string) => number): Timing => {
  const step = ms("--dur-abstract-line-step") || 433;
  const line = ms("--dur-abstract-line") || 267;
  const glide = ms("--dur-abstract-glide") || 400;
  const hold = ms("--dur-loop-step") || 2600;
  return { step, line, glide, hold, cycle: step * BURST + hold };
};

function cell(k: number, c: number) {
  const run = noise(c * 0.21 + k * 3.7, k * 0.53, 1);
  if (run < 0.48) return hash(k, c, 3) > 0.93 ? 1 : 0;
  const inside = noise(c * 0.7, k * 1.3, 2);
  return Math.min(7, 3 + Math.floor(inside * 5));
}

export const archiveMoments = (ms: (n: string) => number) => {
  const { step, cycle } = timing(ms);
  return {
    start: cycle,
    middle: cycle + step * 2 + 200,
    settled: cycle + step * BURST + 1200,
  };
};

export const drawArchive: Draw = (ctx, t, { w, h, tokens, glyph }) => {
  const { step, line, glide, cycle } = timing(tokens.ms);
  const pad = tokens.px(w >= 360 ? "--space-24" : "--space-16");
  const gutter = tokens.px("--space-64") + tokens.px("--space-8");
  const cols = Math.floor((w - pad * 2 - gutter) / CELL_W);
  const x0 = w - pad - cols * CELL_W;
  const top = pad;
  const H = h - pad * 2;
  const full = FULL * CELL_H;
  const Hc = H - full;
  const K = Hc / CELL_H;
  const y = (age: number) =>
    top + (age <= FULL ? age * CELL_H : full + (Hc * (age - FULL)) / (age - FULL + K));
  const pitchAt = (age: number) => (age <= FULL ? CELL_H : (Hc * K) / ((age - FULL + K) * (age - FULL + K)));

  const n = Math.floor(t / cycle);
  const into = t - n * cycle;
  const arrived = Math.min(BURST, Math.floor(into / step) + 1);
  const newest = BASE + n * BURST + arrived - 1;
  const since = into - (arrived - 1) * step;
  const burstOver = into >= BURST * step;
  const glideP = burstOver ? 1 : bezier(tokens.easeOut, clamp01(since / glide));
  const typed = burstOver ? 1 : clamp01((since - (glide - line)) / line);

  let lastY = -Infinity;
  for (let i = 0; i < 4000; i++) {
    const k = newest - i;
    const age = i === 0 ? 0 : i - 1 + glideP;
    const ry = y(age);
    if (ry > top + H) break;
    const pitch = pitchAt(age);
    if (pitch < 0.1) break;
    const dots = pitch < 12;
    if (dots && ry - lastY < 4) continue;
    lastY = ry;
    const alpha = 0.35 + 0.65 * (1 - clamp01(age / 10)) ** 2 - 0.12 * clamp01((ry - top - full) / Hc);
    const shown = i === 0 ? Math.floor(cols * typed) : cols;
    for (let c = 0; c < shown; c++) {
      const base = cell(k, c);
      if (!base) continue;
      if (dots) {
        glyph(1, x0 + c * CELL_W, Math.round(ry) - 11, alpha);
        continue;
      }
      const level = Math.max(1, base - Math.floor(age / 2));
      glyph(level, x0 + c * CELL_W, Math.round(ry) - CELL_H / 2, alpha);
    }
  }

  for (let yy = lastY + 4, j = 0; yy <= top + H; yy += 4, j++) {
    for (let c = 0; c < cols; c++) {
      if (hash(c, Math.round(yy), 7) > 0.42) continue;
      glyph(1, x0 + c * CELL_W, Math.round(yy) - 11, 0.22);
    }
  }

  ctx.globalAlpha = 1;
  ctx.font = `${tokens.px("--caption-size")}px ${tokens.body}`;
  ctx.textAlign = "right";
  ctx.textBaseline = "middle";
  for (const [age, label] of MARKS) {
    ctx.fillStyle = age === 0 ? tokens.text2 : tokens.text3;
    ctx.fillText(label, x0 - 16, Math.round(y(age)));
  }
};

// The tag field drawing (abstract/tags): a field of characters resolves into tags, one at a time.
import { SETTLE } from "@/lib/effects/abstract-motion";
import { CELL_H, CELL_W, RAMP, clamp01, hash, noise, type Draw } from "@/lib/effects/abstract";

export type Tag = { label: string; value: string };

const STEP = 1000 / 30;
const LEAD = 800;

type Timing = {
  tag: number;
  gather: number;
  decode: number;
  hold: number;
  close: number;
  out: number;
  loop: number;
};
const timing = (ms: (n: string) => number, count: number): Timing => {
  const tag = ms("--dur-abstract-tag-step") || 2000;
  const gather = ms("--dur-abstract-gather") || 400;
  const decode = ms("--dur-abstract-decode") || 600;
  const hold = ms("--dur-loop-step") || 2600;
  const close = ms("--dur-abstract-line") || 267;
  const out = LEAD + (count - 1) * tag + gather + decode + hold;
  const loop = out + (count - 1) * 2 * STEP + 4 * STEP + close + 200;
  return { tag, gather, decode, hold, close, out, loop };
};

export const tagMoments = (ms: (n: string) => number, count: number) => {
  const T = timing(ms, count);
  return {
    start: LEAD - 200,
    middle: LEAD + T.tag + T.gather + T.decode * 0.5,
    settled: T.out - T.hold / 2,
  };
};

function layout(cols: number, rows: number, widths: number[]) {
  const spots = [
    { c: 2, r: Math.round(rows * 0.18) },
    { c: cols - 2 - widths[1], r: Math.round(rows * 0.45) },
    { c: 4, r: Math.round(rows * 0.72) },
  ];
  return widths.map((wc, i) => {
    const s = spots[i % spots.length];
    const c = Math.max(1, Math.min(cols - wc - 1, s.c));
    return { c, r: Math.min(rows - 3, s.r), wc, hc: 2 };
  });
}

export function makeDrawTags(tags: Tag[]): Draw {
  return (ctx, t, { w, h, tokens, glyph }) => {
    const T = timing(tokens.ms, tags.length);
    const pad = tokens.px(w >= 360 ? "--space-24" : "--space-16");
    const cols = Math.floor((w - pad * 2) / CELL_W);
    const rows = Math.floor((h - pad * 2) / CELL_H);
    const x0 = Math.round((w - cols * CELL_W) / 2);
    const y0 = Math.round((h - rows * CELL_H) / 2);
    const lt = t % T.loop;
    const frame = Math.floor(t / STEP);
    const drift = (tokens.ms("--search-drift") || 8) / CELL_W;

    ctx.font = `${tokens.px("--caption-size")}px ${tokens.body}`;
    const parts = tags.map((g) => {
      const label = ctx.measureText(g.label).width;
      const value = ctx.measureText(g.value).width;
      return { label, value, width: label + 8 + value };
    });
    const boxes = layout(
      cols,
      rows,
      parts.map((p) => Math.ceil((p.width + 24) / CELL_W)),
    );

    const states = tags.map((_, i) => {
      const s = LEAD + i * T.tag;
      const cutIn = s + T.gather;
      const outAt = T.out + (tags.length - 1 - i) * 2 * STEP;
      const gone = outAt + 4 * STEP;
      const gather = lt < s ? 0 : lt < cutIn ? clamp01((lt - s) / T.gather) : 0;
      const on = lt >= cutIn && lt < gone;
      const fIn = Math.floor((lt - cutIn) / STEP);
      const fOut = Math.floor((gone - lt) / STEP);
      const scale = !on
        ? 1
        : lt < outAt
          ? SETTLE[Math.min(fIn, SETTLE.length - 1)]
          : SETTLE[Math.max(0, fOut)];
      const decoded = clamp01((lt - cutIn) / T.decode);
      const closing = lt >= gone ? clamp01((lt - gone) / T.close) : 1;
      return { gather, on, scale, decoded, closing, cleared: on };
    });

    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const v =
          noise(c * 0.12 + (t / 1000) * drift * 0.12, r * 0.24, 0) * 0.7 +
          noise(c * 0.41, r * 0.7, frame % 2) * 0.3;
        let level = Math.min(7, Math.floor(v ** 1.8 * 9));
        let alpha = 0.35;
        for (let i = 0; i < boxes.length; i++) {
          const b = boxes[i];
          if (c < b.c - 1 || c > b.c + b.wc || r < b.r - 1 || r > b.r + b.hc) continue;
          const st = states[i];
          const seed = hash(c, r, i);
          if (st.cleared) level = 0;
          else if (st.gather > 0) {
            if (seed < st.gather) {
              level = 6 + (seed > 0.5 ? 1 : 0);
              alpha = 0.35 + 0.65 * st.gather;
            }
          } else if (st.closing < 1 && seed > st.closing) level = 0;
        }
        if (level > 0) glyph(level, x0 + c * CELL_W, y0 + r * CELL_H, alpha);
      }
    }

    ctx.globalAlpha = 1;
    ctx.textBaseline = "middle";
    ctx.textAlign = "left";
    boxes.forEach((b, i) => {
      const st = states[i];
      if (!st.on) return;
      const bw = b.wc * CELL_W;
      const bh = b.hc * CELL_H;
      const cx = x0 + b.c * CELL_W + bw / 2;
      const cy = y0 + b.r * CELL_H + bh / 2;
      ctx.save();
      ctx.translate(cx, cy);
      ctx.scale(st.scale, st.scale);
      ctx.translate(-bw / 2, -bh / 2);
      ctx.fillStyle = tokens.bg;
      ctx.beginPath();
      ctx.roundRect(0, 0, bw, bh, tokens.px("--radius-m"));
      ctx.fill();
      ctx.strokeStyle = tokens.line;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.roundRect(0.5, 0.5, bw - 1, bh - 1, tokens.px("--radius-m"));
      ctx.stroke();

      const text = `${tags[i].label} ${tags[i].value}`;
      const shown = Math.floor(text.length * st.decoded);
      const p = parts[i];
      const left = (bw - p.width) / 2;
      let x = left;
      for (let k = 0; k < text.length; k++) {
        const ch = text[k];
        const isLabel = k < tags[i].label.length;
        const advance = k === tags[i].label.length ? 8 : ctx.measureText(ch).width;
        if (ch !== " ") {
          if (k < shown) {
            ctx.globalAlpha = 1;
            ctx.fillStyle = isLabel ? tokens.text3 : tokens.text;
            ctx.fillText(ch, x, bh / 2);
          } else if (k < shown + 6) {
            const level = 1 + Math.floor(hash(k, frame, i) * (RAMP.length - 1));
            glyph(level, x, bh / 2 - CELL_H / 2, 0.6);
          }
        }
        x += advance;
      }
      ctx.restore();
    });
  };
}

export const tagLoop = (ms: (n: string) => number, count: number) => timing(ms, count).loop;

// The brand graph drawing (abstract/graph): the brand in the middle, linked to clusters of its records, and those
// records linked to each other.
import { FRAMES, PRESS, PRESS_FROM, PROGRESS, SCALE, TWIST } from "@/lib/effects/abstract-motion";
import { bezier, clamp01, hash, type Bezier, type Draw } from "@/lib/effects/abstract";

export type Cluster = { label: string; angle: number; count: number };

const STEP = 1000 / 60;
const OPEN = 137;
const PROXY = 0.075;
const RADIUS = 295.83;

const LINKS: [[number, number], [number, number]][] = [
  [
    [0, 4],
    [1, 0],
  ],
  [
    [0, 0],
    [2, 4],
  ],
  [
    [2, 0],
    [3, 3],
  ],
  [
    [3, 0],
    [1, 3],
  ],
];

type Timing = { hold: number; stagger: number; draw: number; loop: number; ease: Bezier };
const timing = (ms: (n: string) => number, ease: Bezier): Timing => {
  const hold = ms("--dur-loop-step") || 2600;
  const stagger = ms("--dur-proof-stagger") || 70;
  const draw = ms("--dur-proof-swap") || 600;
  return { hold, stagger, draw, loop: FRAMES * STEP + hold, ease };
};

function frameAt(t: number, T: Timing) {
  const lt = t % T.loop;
  const openAt = OPEN * STEP;
  if (lt < openAt) return { f: Math.floor(lt / STEP), held: 0 };
  if (lt < openAt + T.hold) return { f: OPEN, held: lt - openAt };
  return { f: Math.min(FRAMES - 1, Math.floor((lt - T.hold) / STEP)), held: T.hold };
}

export const graphMoments = (ms: (n: string) => number) => {
  const hold = ms("--dur-loop-step") || 2600;
  return {
    start: 40 * STEP,
    middle: OPEN * STEP + 300,
    settled: OPEN * STEP + hold - 300,
  };
};

export function makeDrawGraph(brand: string, clusters: Cluster[]): Draw {
  return (ctx, t, { w, h, tokens, glyph }) => {
    const T = timing(tokens.ms, tokens.bez("--ease-proof", [0, 0, 0.58, 1]));
    const { f, held } = frameAt(t, T);
    const unit = (Math.min(w, h) * PROXY) / 100;
    const cx = w / 2;
    const cy = h / 2;
    const p = PROGRESS[f];
    const scale = SCALE[f];
    const twist = TWIST * (1 - p);
    const R = RADIUS * unit * p;
    const press = f >= PRESS_FROM && f < PRESS_FROM + PRESS.length ? PRESS[f - PRESS_FROM] : 1;
    const DEG = Math.PI / 180;

    const ringR = RADIUS * unit;
    for (const [rr, level, alpha] of [
      [ringR, 2, 0.22],
      [ringR * 0.55, 1, 0.18],
    ] as const) {
      const n = Math.floor((2 * Math.PI * rr) / 10);
      for (let i = 0; i < n; i++) {
        if (hash(i, rr) > 0.7) continue;
        const a = (i / n) * 2 * Math.PI;
        glyph(level, Math.round(cx + Math.cos(a) * rr - 4), Math.round(cy + Math.sin(a) * rr - 10), alpha);
      }
    }

    const hubs = clusters.map((cl) => {
      const a = (cl.angle + twist) * DEG;
      return { x: cx + Math.cos(a) * R, y: cy + Math.sin(a) * R };
    });
    const recordR = 44 * unit * scale;
    const records = clusters.map((cl, i) =>
      Array.from({ length: cl.count }, (_, k) => {
        const spread = (k - (cl.count - 1) / 2) * 34 + (hash(i, k) - 0.5) * 12;
        const a = (cl.angle + spread) * DEG;
        const d = recordR * (1.6 + hash(k, i, 2) * 1.2);
        return { x: hubs[i].x + Math.cos(a) * d, y: hubs[i].y + Math.sin(a) * d };
      }),
    );
    const out = f > 0 && f < 168;

    ctx.lineWidth = 1;
    if (out) {
      ctx.globalAlpha = 1;
      ctx.strokeStyle = tokens.lineStrong;
      ctx.beginPath();
      hubs.forEach((hub, i) => {
        ctx.moveTo(cx, cy);
        ctx.lineTo(hub.x, hub.y);
        for (const r of records[i]) {
          ctx.moveTo(hub.x, hub.y);
          ctx.lineTo(r.x, r.y);
        }
      });
      ctx.stroke();

      LINKS.forEach(([[ca, ra], [cb, rb]], i) => {
        const from = records[ca][ra];
        const to = records[cb][rb];
        if (!from || !to) return;
        const start = i * T.stagger * 4;
        const k = f > OPEN ? 1 : bezier(T.ease, clamp01((held - start) / T.draw));
        if (k <= 0) return;
        const mx = (from.x + to.x) / 2;
        const my = (from.y + to.y) / 2;
        const dx = mx - cx;
        const dy = my - cy;
        const len = Math.hypot(dx, dy);
        const nx = len > 8 ? dx / len : -(to.y - from.y) / Math.hypot(to.x - from.x, to.y - from.y);
        const ny = len > 8 ? dy / len : (to.x - from.x) / Math.hypot(to.x - from.x, to.y - from.y);
        const bow = len > 8 ? R * 0.35 : R * 0.6;
        const qx = mx + nx * bow;
        const qy = my + ny * bow;
        ctx.globalAlpha = 1;
        ctx.strokeStyle = k < 1 && f <= OPEN ? tokens.text : tokens.text3;
        ctx.beginPath();
        const steps = 24;
        for (let s = 0; s <= Math.ceil(steps * k); s++) {
          const u = Math.min(s / steps, k);
          const x = (1 - u) * (1 - u) * from.x + 2 * (1 - u) * u * qx + u * u * to.x;
          const y = (1 - u) * (1 - u) * from.y + 2 * (1 - u) * u * qy + u * u * to.y;
          if (s === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
        ctx.stroke();
      });

      ctx.fillStyle = tokens.text;
      records.forEach((rs) =>
        rs.forEach((r) => {
          ctx.globalAlpha = 0.85;
          ctx.fillRect(Math.round(r.x - 2), Math.round(r.y - 2), 4, 4);
        }),
      );
      hubs.forEach((hub) => {
        ctx.globalAlpha = 1;
        const s = Math.round(8 * scale);
        ctx.fillRect(Math.round(hub.x - s / 2), Math.round(hub.y - s / 2), s, s);
      });

      const labelAlpha = clamp01((p - 0.8) / 0.1);
      if (labelAlpha > 0) {
        ctx.font = `${tokens.px("--caption-size")}px ${tokens.body}`;
        ctx.textBaseline = "middle";
        clusters.forEach((cl, i) => {
          const right = Math.cos(cl.angle * DEG) > 0;
          const below = Math.sin(cl.angle * DEG) > 0;
          ctx.globalAlpha = labelAlpha;
          ctx.fillStyle = tokens.text3;
          ctx.textAlign = right ? "left" : "right";
          const lx = hubs[i].x + Math.cos(cl.angle * DEG) * recordR * 3.6;
          const ly = hubs[i].y + Math.sin(cl.angle * DEG) * recordR * 3.6 + (below ? 8 : -8);
          const pad = tokens.px("--space-16");
          const tw = ctx.measureText(cl.label).width;
          const x = right ? Math.min(lx, w - pad - tw) : Math.max(lx, pad + tw);
          ctx.fillText(cl.label, x, ly);
        });
      }
    }

    ctx.globalAlpha = 1;
    ctx.fillStyle = tokens.text;
    const s = 16 * press;
    ctx.fillRect(Math.round(cx - s / 2), Math.round(cy - s / 2), Math.round(s), Math.round(s));
    ctx.font = `${tokens.px("--caption-size")}px ${tokens.body}`;
    ctx.textAlign = "center";
    ctx.textBaseline = "top";
    ctx.fillStyle = tokens.text2;
    ctx.fillText(brand, cx, cy + 16);
  };
}

export const graphLoop = (ms: (n: string) => number) => FRAMES * STEP + (ms("--dur-loop-step") || 2600);

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}
